const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const NOTION_TOKEN = process.env.NOTION_TOKEN;
const NOTION_DB = process.env.NOTION_TASKS_DB_ID;
const LINEAR_API_KEY = process.env.LINEAR_API_KEY;
const LINEAR_TEAM_ID = process.env.LINEAR_TEAM_ID || '';
const STATE_PATH = process.env.N8N_SYNC_STATE_PATH || '/home/node/.n8n-files/notion-linear-sync/sync_state.json';
const CONFLICT_STRATEGY = process.env.CONFLICT_STRATEGY || 'last-write-wins';
const NOTION_VERSION = '2022-06-28';
const PRIORITY_MAP = { Low: 4, Medium: 3, High: 2, Urgent: 1 };
const PRIORITY_REVERSE = { 1: 'Urgent', 2: 'High', 3: 'Medium', 4: 'Low' };
const STATUS_ALIAS = { backlog: 'backlog', unstarted: 'unstarted', todo: 'backlog', 'to do': 'backlog', 'to-do': 'backlog', 'not started': 'unstarted', planned: 'backlog', triage: 'backlog', started: 'started', 'in progress': 'started', 'in-progress': 'started', inprogress: 'started', active: 'started', doing: 'started', 'in review': 'started', review: 'started', done: 'completed', complete: 'completed', completed: 'completed', canceled: 'canceled', cancelled: 'canceled' };
const TASK_TYPES = ['Redo', 'Plan', 'Fix', 'Test', 'Design', 'Research', 'Write', 'Build', 'Organize', 'Study', 'Watch', 'Share'];

function sha(data) { return crypto.createHash('sha256').update(JSON.stringify(data)).digest('hex').slice(0, 16); }
function ensureStateFile() { const dir = path.dirname(STATE_PATH); fs.mkdirSync(dir, { recursive: true }); if (!fs.existsSync(STATE_PATH)) fs.writeFileSync(STATE_PATH, JSON.stringify({ version: 1, entities: { project: [], milestone: [], task: [] } }, null, 2)); }
function loadState() { ensureStateFile(); try { return JSON.parse(fs.readFileSync(STATE_PATH, 'utf8')); } catch { return { version: 1, entities: { project: [], milestone: [], task: [] } }; } }
function saveState(state) { ensureStateFile(); fs.writeFileSync(STATE_PATH, JSON.stringify(state, null, 2)); }
function upsertState(state, record) { const bucket = state.entities.task || []; state.entities.task = bucket.filter((entry) => !(entry.notionId && entry.notionId === record.notionId) && !(entry.linearId && entry.linearId === record.linearId)); state.entities.task.push(record); }
async function notionRequest(endpoint, options = {}) { const response = await fetch(`https://api.notion.com/v1${endpoint}`, { ...options, headers: { Authorization: `Bearer ${NOTION_TOKEN}`, 'Notion-Version': NOTION_VERSION, 'Content-Type': 'application/json', ...(options.headers || {}) } }); const body = await response.json(); if (!response.ok) throw new Error(`Notion ${endpoint} failed: ${response.status} ${JSON.stringify(body)}`); return body; }
async function linearRequest(query, variables = {}) { const response = await fetch('https://api.linear.app/graphql', { method: 'POST', headers: { Authorization: LINEAR_API_KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ query, variables }) }); const body = await response.json(); if (!response.ok || body.errors) throw new Error(`Linear request failed: ${JSON.stringify(body.errors || body)}`); return body.data; }
const richText = (value) => value ? [{ text: { content: value } }] : [];
const title = (prop) => (prop?.title || []).map((entry) => entry.plain_text || entry.text?.content || '').join('').trim();
const rich = (prop) => (prop?.rich_text || []).map((entry) => entry.plain_text || entry.text?.content || '').join('').trim();
const selectName = (prop) => prop?.select?.name || null;
const dateValue = (prop) => prop?.date?.start || null;
const relationId = (prop) => prop?.relation?.[0]?.id || null;
const checkbox = (prop) => Boolean(prop?.checkbox);
function notionStatusToLinearType(status, complete) { if (complete) return 'completed'; if (!status) return null; return STATUS_ALIAS[String(status).trim().toLowerCase()] || null; }
function notionStatusMatchesLinear(status, linearStateName, linearStateType) { const notionType = notionStatusToLinearType(status, false); if (!status && !linearStateName && !linearStateType) return true; if (status && linearStateName && String(status).trim().toLowerCase() === String(linearStateName).trim().toLowerCase()) return true; return notionType && linearStateType ? notionType === linearStateType : false; }
function linearStateToNotionStatus(name, type) { return name || ({ backlog: 'Backlog', unstarted: 'Unstarted', started: 'In Progress', completed: 'Done', canceled: 'Canceled' })[type] || 'Backlog'; }
function notionToUnified(page) { const props = page.properties || {}; const labels = selectName(props.type); const status = selectName(props.status); const record = { notionId: page.id, linearId: rich(props['linear id']), title: title(props.task), complete: checkbox(props.complete), status, priority: selectName(props.priority), dueDate: dateValue(props['due date']), taskType: labels, projectNotionId: relationId(props.project), milestoneNotionId: relationId(props.milestones), parentTaskNotionId: relationId(props['parent task']), updatedAt: page.last_edited_time, linearSync: checkbox(props['linear sync']) }; record.linearStateType = notionStatusToLinearType(record.status, record.complete); record.priorityLinear = PRIORITY_MAP[record.priority] || 0; record.contentHash = sha({ title: record.title, complete: record.complete, statusType: record.linearStateType || null, priority: record.priority || null, dueDate: record.dueDate || null, taskType: record.taskType || null, projectNotionId: record.projectNotionId || null, milestoneNotionId: record.milestoneNotionId || null, parentTaskNotionId: record.parentTaskNotionId || null }); return record; }
function linearToUnified(issue) { const labels = issue.labels?.nodes?.map((entry) => entry.name) || []; const taskType = labels.find((name) => TASK_TYPES.includes(name)) || null; const record = { notionId: null, linearId: issue.id, title: issue.title, description: issue.description || '', complete: issue.state?.type === 'completed', status: linearStateToNotionStatus(issue.state?.name, issue.state?.type), linearStateName: issue.state?.name || null, linearStateType: issue.state?.type || null, priority: PRIORITY_REVERSE[issue.priority] || null, priorityLinear: issue.priority || 0, dueDate: issue.dueDate || null, taskType, projectLinearId: issue.project?.id || null, milestoneLinearId: issue.projectMilestone?.id || null, parentTaskLinearId: issue.parent?.id || null, updatedAt: issue.updatedAt, linearUrl: issue.url || null }; record.contentHash = sha({ title: record.title, complete: record.complete, statusType: record.linearStateType || null, priority: record.priority || null, dueDate: record.dueDate || null, taskType: record.taskType || null, projectLinearId: record.projectLinearId || null, milestoneLinearId: record.milestoneLinearId || null, parentTaskLinearId: record.parentTaskLinearId || null }); return record; }
async function fetchNotionTasks() { let cursor; const records = []; do { const body = { page_size: 100, filter: { property: 'linear sync', checkbox: { equals: true } } }; if (cursor) body.start_cursor = cursor; const response = await notionRequest(`/databases/${NOTION_DB}/query`, { method: 'POST', body: JSON.stringify(body) }); records.push(...response.results.map(notionToUnified)); cursor = response.has_more ? response.next_cursor : null; } while (cursor); return records; }
async function fetchLinearBundle() { const query = `query TaskBundle($teamId: String) { issues(first: 250, filter: { team: $teamId ? { id: { eq: $teamId } } : undefined }) { nodes { id title description dueDate priority updatedAt url state { id name type } labels { nodes { id name } } project { id } projectMilestone { id } parent { id } } } workflowStates(first: 250) { nodes { id name type team { id } } } issueLabels(first: 250) { nodes { id name } } }`; const data = await linearRequest(query, { teamId: LINEAR_TEAM_ID || undefined }); return { issues: (data.issues?.nodes || []).map(linearToUnified), workflowStates: data.workflowStates?.nodes || [], labels: data.issueLabels?.nodes || [] }; }
function getStateFor(state, notionId, linearId) { return (state.entities.task || []).find((entry) => (notionId && entry.notionId === notionId) || (linearId && entry.linearId === linearId)) || null; }
function asMillis(value) { if (!value) return 0; const date = new Date(value); return Number.isNaN(date.getTime()) ? 0 : date.getTime(); }
function chooseWinner(notionRecord, linearRecord, state) { if (!state) return asMillis(notionRecord.updatedAt) >= asMillis(linearRecord.updatedAt) ? 'notion' : 'linear'; const notionChanged = asMillis(notionRecord.updatedAt) > asMillis(state.notionLastModified); const linearChanged = asMillis(linearRecord.updatedAt) > asMillis(state.linearLastModified); if (notionChanged && !linearChanged) return 'notion'; if (linearChanged && !notionChanged) return 'linear'; if (!notionChanged && !linearChanged) return 'none'; if (CONFLICT_STRATEGY === 'notion-primary') return 'notion'; if (CONFLICT_STRATEGY === 'linear-primary') return 'linear'; return asMillis(notionRecord.updatedAt) >= asMillis(linearRecord.updatedAt) ? 'notion' : 'linear'; }
function sortTaskChanges(changes) { const byId = new Map(); for (const change of changes) { const id = change.record.notionId || change.record.linearId; if (id) byId.set(id, change); } const ordered = []; const visited = new Set(); const active = new Set(); const errors = []; function walk(change) { const id = change.record.notionId || change.record.linearId; if (!id || visited.has(id)) return; if (active.has(id)) { errors.push(`task cycle ${id}`); return; } active.add(id); const parentId = change.record.parentTaskNotionId || change.record.parentTaskLinearId; if (parentId && byId.has(parentId)) walk(byId.get(parentId)); active.delete(id); visited.add(id); ordered.push(change); } for (const change of changes) walk(change); return { ordered, errors }; }
function notionProps(record, relationMaps) { const props = { task: { title: [{ text: { content: record.title } }] }, 'linear id': { rich_text: richText(record.linearId) }, 'linear sync': { checkbox: true }, complete: { checkbox: Boolean(record.complete) }, status: { select: { name: linearStateToNotionStatus(record.linearStateName, record.linearStateType) } }, priority: record.priority ? { select: { name: record.priority } } : undefined, 'due date': record.dueDate ? { date: { start: record.dueDate } } : undefined, type: record.taskType ? { select: { name: record.taskType } } : undefined, project: relationMaps.project ? { relation: [{ id: relationMaps.project }] } : undefined, milestones: relationMaps.milestone ? { relation: [{ id: relationMaps.milestone }] } : undefined, 'parent task': relationMaps.parent ? { relation: [{ id: relationMaps.parent }] } : undefined, url: record.linearUrl ? { url: record.linearUrl } : undefined }; return Object.fromEntries(Object.entries(props).filter(([, value]) => value !== undefined)); }
(async () => {
  const state = loadState();
  const projectStates = state.entities.project || [];
  const milestoneStates = state.entities.milestone || [];
  const taskStates = state.entities.task || [];
  const projectNotionToLinear = new Map(projectStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.notionId, entry.linearId]));
  const projectLinearToNotion = new Map(projectStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.linearId, entry.notionId]));
  const milestoneNotionToLinear = new Map(milestoneStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.notionId, entry.linearId]));
  const milestoneLinearToNotion = new Map(milestoneStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.linearId, entry.notionId]));
  const taskNotionToLinear = new Map(taskStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.notionId, entry.linearId]));
  const taskLinearToNotion = new Map(taskStates.filter((entry) => entry.notionId && entry.linearId).map((entry) => [entry.linearId, entry.notionId]));
  const notionTasks = await fetchNotionTasks();
  const { issues: linearTasks, workflowStates, labels } = await fetchLinearBundle();
  const linearById = new Map(linearTasks.map((record) => [record.linearId, record]));
  const labelByName = new Map(labels.map((label) => [label.name, label.id]));
  const stateIdByType = new Map(workflowStates.map((state) => [state.type, state.id]));
  const touchedLinearIds = new Set();
  const changes = [];
  const summary = { success: true, entityType: 'task', createdToLinear: 0, updatedToLinear: 0, createdToNotion: 0, updatedToNotion: 0, tasksCount: 0, errors: [] };

  for (const notionRecord of notionTasks) {
    const linearRecord = notionRecord.linearId ? linearById.get(notionRecord.linearId) : undefined;
    notionRecord.projectLinearId = projectNotionToLinear.get(notionRecord.projectNotionId) || null;
    notionRecord.milestoneLinearId = milestoneNotionToLinear.get(notionRecord.milestoneNotionId) || null;
    notionRecord.parentTaskLinearId = taskNotionToLinear.get(notionRecord.parentTaskNotionId) || null;
    if (!linearRecord) { changes.push({ action: 'create', source: 'notion', target: 'linear', record: notionRecord }); continue; }
    touchedLinearIds.add(linearRecord.linearId);
    const stateRecord = getStateFor(state, notionRecord.notionId, linearRecord.linearId);
    const statusEquivalent = notionStatusMatchesLinear(notionRecord.status, linearRecord.linearStateName, linearRecord.linearStateType) && Boolean(notionRecord.complete) === Boolean(linearRecord.complete);
    if (notionRecord.contentHash === linearRecord.contentHash || statusEquivalent && notionRecord.title === linearRecord.title && notionRecord.priority === linearRecord.priority && notionRecord.dueDate === linearRecord.dueDate && notionRecord.taskType === linearRecord.taskType) {
      upsertState(state, { entityType: 'task', notionId: notionRecord.notionId, linearId: linearRecord.linearId, notionLastModified: notionRecord.updatedAt, linearLastModified: linearRecord.updatedAt, contentHash: notionRecord.contentHash, lastSynced: new Date().toISOString() });
      continue;
    }
    const winner = chooseWinner(notionRecord, linearRecord, stateRecord);
    if (winner === 'notion') changes.push({ action: 'update', source: 'notion', target: 'linear', record: notionRecord, counterpart: linearRecord });
    else if (winner === 'linear') changes.push({ action: 'update', source: 'linear', target: 'notion', record: linearRecord, counterpart: notionRecord });
  }
  for (const linearRecord of linearTasks) { if (!touchedLinearIds.has(linearRecord.linearId)) changes.push({ action: 'create', source: 'linear', target: 'notion', record: linearRecord }); }

  const sorted = sortTaskChanges(changes);
  if (sorted.errors.length) { summary.success = false; summary.errors.push(...sorted.errors); }

  for (const change of sorted.ordered) {
    if (change.source === 'notion') {
      const record = change.record;
      if (!record.projectLinearId) { summary.success = false; summary.errors.push(`missing project mapping for notion task ${record.notionId}`); continue; }
      const input = { title: record.title, description: record.description || undefined, teamId: LINEAR_TEAM_ID || undefined, projectId: record.projectLinearId, projectMilestoneId: record.milestoneLinearId || undefined, parentId: record.parentTaskLinearId || undefined, priority: record.priorityLinear || undefined, dueDate: record.dueDate || undefined, labelIds: record.taskType && labelByName.has(record.taskType) ? [labelByName.get(record.taskType)] : undefined, stateId: stateIdByType.get(record.linearStateType || 'backlog') || undefined };
      try {
        if (change.action === 'create') {
          const data = await linearRequest(`mutation CreateIssue($input: IssueCreateInput!) { issueCreate(input: $input) { success issue { id updatedAt url state { id name type } } } }`, { input });
          const issue = data.issueCreate.issue;
          await notionRequest(`/pages/${record.notionId}`, { method: 'PATCH', body: JSON.stringify({ properties: { 'linear id': { rich_text: richText(issue.id) }, url: { url: issue.url } } }) });
          taskNotionToLinear.set(record.notionId, issue.id);
          upsertState(state, { entityType: 'task', notionId: record.notionId, linearId: issue.id, notionLastModified: record.updatedAt, linearLastModified: issue.updatedAt, contentHash: record.contentHash, lastSynced: new Date().toISOString() });
          summary.createdToLinear += 1;
        } else {
          const data = await linearRequest(`mutation UpdateIssue($id: String!, $input: IssueUpdateInput!) { issueUpdate(id: $id, input: $input) { success issue { id updatedAt state { id name type } url } } }`, { id: change.counterpart.linearId, input });
          const issue = data.issueUpdate.issue;
          upsertState(state, { entityType: 'task', notionId: record.notionId, linearId: change.counterpart.linearId, notionLastModified: record.updatedAt, linearLastModified: issue.updatedAt, contentHash: record.contentHash, lastSynced: new Date().toISOString() });
          summary.updatedToLinear += 1;
        }
      } catch (error) { summary.success = false; summary.errors.push(`${change.action} linear task ${record.notionId}: ${error.message}`); }
    } else {
      const record = change.record;
      const relationMaps = { project: projectLinearToNotion.get(record.projectLinearId) || null, milestone: milestoneLinearToNotion.get(record.milestoneLinearId) || null, parent: taskLinearToNotion.get(record.parentTaskLinearId) || null };
      try {
        if (change.action === 'create') {
          const page = await notionRequest('/pages', { method: 'POST', body: JSON.stringify({ parent: { database_id: NOTION_DB }, properties: notionProps(record, relationMaps) }) });
          taskLinearToNotion.set(record.linearId, page.id);
          upsertState(state, { entityType: 'task', notionId: page.id, linearId: record.linearId, notionLastModified: page.last_edited_time, linearLastModified: record.updatedAt, contentHash: record.contentHash, lastSynced: new Date().toISOString() });
          summary.createdToNotion += 1;
        } else {
          const pageId = change.counterpart?.notionId || taskLinearToNotion.get(record.linearId);
          if (!pageId) throw new Error(`missing notion page for linear task ${record.linearId}`);
          const page = await notionRequest(`/pages/${pageId}`, { method: 'PATCH', body: JSON.stringify({ properties: notionProps(record, relationMaps) }) });
          upsertState(state, { entityType: 'task', notionId: pageId, linearId: record.linearId, notionLastModified: page.last_edited_time, linearLastModified: record.updatedAt, contentHash: record.contentHash, lastSynced: new Date().toISOString() });
          summary.updatedToNotion += 1;
        }
      } catch (error) { summary.success = false; summary.errors.push(`${change.action} notion task ${record.linearId}: ${error.message}`); }
    }
  }

  saveState(state);
  summary.tasksCount = summary.createdToLinear + summary.updatedToLinear + summary.createdToNotion + summary.updatedToNotion;
  summary.status = summary.errors.length ? 'completed_with_errors' : 'success';
  summary.details = summary.errors.length ? summary.errors.join(' | ').slice(0, 1900) : `Tasks synced: ${summary.tasksCount}`;
  process.stdout.write(JSON.stringify(summary));
})().catch((error) => { process.stdout.write(JSON.stringify({ success: false, entityType: 'task', status: 'failed', tasksCount: 0, details: error.message.slice(0, 1900), errors: [error.message] })); process.exitCode = 1; });
